const first_name=parts.length>1?parts.slice(0,-1).join(' '):(parts[0]||'there');
const last_name =parts.length>1?parts[parts.length-1]:(parts[0]||'Unknown');
const FREE=new Set(['gmail.com','yahoo.com','hotmail.com','outlook.com','icloud.com','aol.com','proton.me','protonmail.com','live.com','msn.com','me.com']);
