if(website) domain=website.replace(/^https?:\/\//i,'').replace(/^www\./i,'').split('/')[0].toLowerCase();
else if(email.includes('@')){const d=email.split('@')[1].toLowerCase(); if(!FREE.has(d)) domain=d;}
