parameters.jsCode:
const lead  = $('Normalize Input').first().json;
const agent = $input.first().json;
const raw   = agent.output ?? agent.text ?? '';

let p;
try { const m = String(raw).match(/\{[\s\S]*\}/); p = JSON.parse(m ? m[0] : raw); }
catch (e) {
  return [{ json: { ...lead, ok:false, grounded:false, company_intel:{}, sources_cited:[],
    citation_warnings:['agent returned unparseable output'],
    intel_text:'Enrichment failed: the agent did not return usable output.',
    raw:String(raw).slice(0,600) } }];
}

// Everything the tools actually returned this run.
let evidence = '';
for (const s of (agent.intermediateSteps || [])) {
  evidence += ' ' + (typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation ?? ''));
}
evidence = evidence.replace(/\\n/g, ' ').toLowerCase();
const haveEvidence = evidence.trim().length > 200;

const warnings = [];
const cited = [];

const cleanSource = (src, label) => {
  const s = String(src || '').trim();
  if (!s) { warnings.push(label + ': no source given'); return null; }
  const urls = s.match(/https?:\/\/[^\s,;)\]]+/g) || [];
  if (!urls.length) { warnings.push(label + ': source is not a URL'); return null; }
  if (urls.length > 1) warnings.push(label + ': ' + urls.length + ' URLs in one citation, kept first');
  return urls[0].replace(/[.,)]+$/, '');
};

const figuresIn = txt => (String(txt).match(/\d[\d,]*\.?\d*%?/g) || [])
  .map(x => x.replace(/[.,]+$/, ''))
  .filter(x => x.replace(/[^\d]/g, '').length >= 2);

const keep = (o, label) => {
  if (!o || typeof o !== 'object') return null;
  const claim = String(o.claim || '').trim();
  if (!claim) return null;
  const src = cleanSource(o.source, label);
  if (!src) { warnings.push(label + ': dropped, unverifiable citation'); return null; }
  if (haveEvidence) {
    const missing = figuresIn(claim).filter(f => !evidence.includes(f.toLowerCase()));
    if (missing.length) {
      warnings.push(label + ': DROPPED - figure(s) ' + missing.join(', ') +
                    ' do not appear in retrieved evidence (likely from model memory)');
      return null;
    }
  }
  cited.push(src);
  return { claim, source: src };
};

const co = p.company || {};
const out = {
  name: co.name || null,
  what_they_do: keep(co.what_they_do, 'what_they_do'),
  segment:      keep(co.segment, 'segment'),
  signals:      (co.signals || []).map((s,i) => keep(s, 'signal[' + i + ']')).filter(Boolean)
};

const grounded = p.grounded === true && cited.length > 0;

// Human-readable rendering for the CRM record. The structured object above is
// kept for verification; this is what a person actually reads in Salesforce.
const lines = [];
if (!grounded) {
  lines.push('No verified company information could be established from public sources.');
} else {
  if (out.name) lines.push('Company: ' + out.name);
  if (out.what_they_do) lines.push('What they do: ' + out.what_they_do.claim + '\n  Source: ' + out.what_they_do.source);
  if (out.segment)      lines.push('Segment: ' + out.segment.claim + '\n  Source: ' + out.segment.source);
  if (out.signals.length) {
    lines.push('Signals:');
    out.signals.forEach(s => lines.push('  - ' + s.claim + '\n    Source: ' + s.source));
  }
}
if (warnings.length) {
  lines.push('');
  lines.push('Claims removed by verification:');
  warnings.forEach(x => lines.push('  - ' + x));
}
const intel_text = lines.join('\n');

return [{ json: { ...lead, ok:true, grounded,
  company_intel: out,
  intel_text,
  unsupported: p.omitted_because_unsupported || [],
  sources_cited: [...new Set(cited)],
  citation_warnings: warnings,
  evidence_chars: evidence.trim().length } }];

