const lead   = $('Parse + Verify').first().json;
const writer = $('Email Writer Agent').first().json;
const recs   = ($input.first().json.records) || [];
if (!recs.length) throw new Error("EmailTemplate 'Stripe' not found. Run the setup workflow.");
const tpl = recs[0];

let personalized='', subject='', cta='billing';
const raw = writer.output ?? writer.text ?? '';
try {
  const m = String(raw).match(/\{[\s\S]*\}/);
  const wj = JSON.parse(m ? m[0] : raw);
  personalized = wj.body || '';
  subject      = wj.subject || '';
  if (wj.cta) cta = String(wj.cta).toLowerCase().trim();
} catch(e) { personalized = String(raw).trim(); }

// The model picks a CATEGORY only - never a URL. This makes hallucinated links impossible.
const CTA = {
  billing: { url:'https://stripe.com/billing',              label:'Explore Stripe Billing' },
  pricing: { url:'https://stripe.com/pricing',              label:'See pricing' },
  docs:    { url:'https://docs.stripe.com',                 label:'Read the docs' },
  signup:  { url:'https://dashboard.stripe.com/register',   label:'Create an account' }
};
const chosen = CTA[cta] || CTA.billing;

const shell  = tpl.HtmlValue || tpl.Body || '';
const isHtml = !!tpl.HtmlValue;

const asHtml = t => String(t).split(/\n\s*\n|\n/).map(s=>s.trim()).filter(Boolean)
  .map(p => '<p style="margin:0 0 14px;">' + p + '</p>').join('');

const bodyToken = isHtml ? asHtml(personalized) : personalized;

const fill = s => String(s||'')
  .replace(/\[\[FIRST_NAME\]\]/g, lead.first_name || 'there')
  .replace(/\[\[PERSONALIZED_BODY\]\]/g, bodyToken)
  .replace(/\[\[CTA_URL\]\]/g, chosen.url)
  .replace(/\[\[CTA_LABEL\]\]/g, chosen.label)
  .replace(/\[\[SUBJECT\]\]/g, subject);

const wordCount = personalized.split(/\s+/).filter(Boolean).length;

return [{ json: {
  to: lead.email,
  subject: (fill(tpl.Subject) || subject || 'Thanks for reaching out').trim(),
  body: fill(shell),
  is_html: isHtml,
  cta_choice: cta, cta_url: chosen.url, cta_label: chosen.label,
  template_id: tpl.Id, template_name: tpl.Name,
  grounded: lead.grounded, sources_cited: lead.sources_cited,
  citation_warnings: lead.citation_warnings || [],
  word_count: wordCount,
  evidence_chars: lead.evidence_chars ?? null,
  personalized_preview: personalized
}}];
